// Audio sessions and reading grants for the music, book and audiobook fixtures (docs/media-kinds.md).
import { homedir } from 'node:os';
import { join } from 'node:path';
import type { PlaybackPlan, PlaybackRequest, ReadingGrant, ReadingProgress, Title } from '../packages/protocol/types';
import { audioSourceFor, mediaChapters, readingSourceFor } from '../packages/protocol/fixtures/media';
import { sessions, type Session } from './sessions';

/** Generated by mock-server/scripts/make-music-media.ts (music clips and audiobooks). */
export const musicRoot = process.env.VELA_MOCK_MUSIC_ROOT || join(homedir(), '.scratch/tmp/vela/media-music');
/** Generated by mock-server/scripts/make-book-media.ts (EPUB, PDF and CBZ). */
export const booksRoot = process.env.VELA_MOCK_BOOKS_ROOT || join(homedir(), '.scratch/tmp/vela/media-books');

/** Serves one generated file with single byte ranges; 503 with the generator to run when it is missing. */
export async function serveGeneratedFile(req: Request, path: string, mimeType: string, generator: string): Promise<Response> {
  const file = Bun.file(path);
  if (!await file.exists()) return Response.json({ error: 'media_not_generated', message: `Run bun ${generator}` }, { status: 503, headers: { 'Cache-Control': 'no-store' } });
  const headers = new Headers({ 'Content-Type': mimeType, 'Accept-Ranges': 'bytes', 'Cache-Control': 'no-store' });
  let start = 0, end = file.size - 1, status = 200;
  const range = req.headers.get('range');
  if (range) {
    const match = /^bytes=(\d*)-(\d*)$/.exec(range);
    if (!match || (!match[1] && !match[2])) return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${file.size}` } });
    start = match[1] ? Number(match[1]) : Math.max(0, file.size - Number(match[2]));
    end = match[1] && match[2] ? Math.min(Number(match[2]), end) : end;
    if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end) || start > end || start >= file.size)
      return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${file.size}` } });
    headers.set('Content-Range', `bytes ${start}-${end}/${file.size}`); status = 206;
  }
  headers.set('Content-Length', String(end - start + 1));
  return new Response(req.method === 'HEAD' ? null : file.slice(start, end + 1), { status, headers });
}

export const musicGenerator = 'mock-server/scripts/make-music-media.ts';
export const bookGenerator = 'mock-server/scripts/make-book-media.ts';

/** An audio-only plan: one direct, range-capable original file. Tracks never resume; audiobooks and parts do. */
export async function createAudioSession(owner: string, request: PlaybackRequest, title: Title): Promise<Session | undefined> {
  const source = audioSourceFor(title.id);
  if (!source) return undefined;
  const file = Bun.file(join(musicRoot, source.file));
  if (!await file.exists()) return undefined;
  const id = crypto.randomUUID(), token = crypto.randomUUID();
  const resume = title.media?.role === 'track' ? 0 : title.watch?.played ? 0 : title.watch?.positionSeconds ?? 0;
  const timelineId = `audio-${title.id}`;
  const plan: PlaybackPlan = { sessionId: id, revision: 1, sourceGeneration: 1, seekGeneration: 1, titleId: title.id, state: 'ready', media: 'audio',
    positionSeconds: request.positionSeconds ?? resume, durationSeconds: source.durationSeconds,
    paths: [{ id: 'direct', kind: 'direct', transport: 'file', url: `/sessions/media/${id}/${token}/${source.file}`, mimeType: source.mimeType, original: true, range: true,
      byteLength: file.size, sourceId: `source-${title.id}`, timelineId, readiness: 'ready', qualities: [], boundaries: [] }],
    selectedPathId: 'direct', audioTracks: [], subtitleTracks: [], selectedSubtitleTrackId: null, chapters: mediaChapters(title.id),
    fallback: { state: 'unsupported', reason: 'The mock serves the original audio file only.' } };
  const session: Session = { owner, mediaToken: token, plan, history: [], listeners: new Map(), sequence: 0, expires: Date.now() + 86_400_000 };
  sessions.set(id, session);
  return session;
}
/** The single file an audio session may read through its media grant. */
export function serveAudioSession(req: Request, session: Session, resource: string): Promise<Response> {
  const source = session.plan.titleId ? audioSourceFor(session.plan.titleId) : undefined;
  if (!source || resource !== source.file) return Promise.resolve(new Response('Not found', { status: 404 }));
  return serveGeneratedFile(req, join(musicRoot, source.file), source.mimeType, musicGenerator);
}

// Reading grants: opaque, short-lived, fetched without the bearer (like Ether's kind-media ticket).
interface ReadTicket { owner: string; titleId: string; file: string; mimeType: string; expires: number }
const readTickets = new Map<string, ReadTicket>();
export const readTicketSeconds = 15 * 60;
export async function issueReadGrant(owner: string, title: Title, progress: ReadingProgress | undefined): Promise<ReadingGrant | undefined> {
  const source = readingSourceFor(title.id);
  if (!source) return undefined;
  const file = Bun.file(join(booksRoot, source.file));
  if (!await file.exists()) return undefined;
  const token = crypto.randomUUID().replaceAll('-', ''), expires = Date.now() + readTicketSeconds * 1000;
  for (const [key, ticket] of readTickets) if (ticket.expires <= Date.now()) readTickets.delete(key);
  readTickets.set(token, { owner, titleId: title.id, file: source.file, mimeType: source.mimeType, expires });
  return { titleId: title.id, format: source.format, mimeType: source.mimeType, url: `/reading/media/${token}/${source.file}`,
    expiresAt: new Date(expires).toISOString(), byteLength: file.size, ...(progress ? { progress } : {}) };
}
/** GET/HEAD /reading/media/:token/:file. `ownerValid` rejects tickets whose sign-in was revoked. */
export function serveReadTicket(req: Request, token: string, resource: string, ownerValid: (owner: string) => boolean): Promise<Response> | Response {
  const ticket = readTickets.get(token);
  if (!ticket || ticket.expires <= Date.now() || ticket.file !== resource || !ownerValid(ticket.owner) || !['GET', 'HEAD'].includes(req.method))
    return Response.json({ error: { class: 'auth', code: 'invalid_read_grant', message: 'Reading grant expired or revoked', retry: { allowed: false } } }, { status: 401, headers: { 'Cache-Control': 'no-store' } });
  return serveGeneratedFile(req, join(booksRoot, ticket.file), ticket.mimeType, bookGenerator);
}

/** Per-viewer reading state over the fixture's shared watch state. */
export interface ReadingState { reading?: ReadingProgress; played: boolean }
const readingStates = new Map<string, ReadingState>();
const readingKey = (viewerId: string, titleId: string) => `${viewerId}\u0000${titleId}`;
export function readingState(viewerId: string, title: Title): ReadingState {
  return readingStates.get(readingKey(viewerId, title.id)) ?? { reading: title.watch?.reading, played: title.watch?.played ?? false };
}
export function setReadingState(viewerId: string, titleId: string, state: ReadingState): void { readingStates.set(readingKey(viewerId, titleId), state); }
/** A title as one viewer sees it: books carry that viewer's reading progress and finished flag. */
export function withReading(viewerId: string, title: Title): Title {
  if (!title.media?.reading) return title;
  const state = readingState(viewerId, title);
  const { reading: _reading, ...watch } = title.watch ?? { positionSeconds: 0, played: false, favorite: false, watchlisted: false };
  return { ...title, watch: { ...watch, played: state.played, ...(state.reading ? { reading: state.reading, lastViewedAt: state.reading.updatedAt } : {}) } };
}
